import{z as d,x as c,o as E,c as p,q as s,j as i,D as t,d as e,s as l,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"配额","description":"","frontmatter":{"title":"配额","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fs-quota.md","filePath":"cs/fs-quota.md","lastUpdated":1791413859000}'),A={name:"cs/fs-quota.md"};function u(B,a,C,f,m,h){const r=c("Mermaid");return E(),p("div",null,[a[2]||(a[2]=s('<h1 id="配额" tabindex="-1">配额 <a class="header-anchor" href="#配额" aria-label="Permalink to &quot;配额&quot;">​</a></h1><div class="epigraph"><p>配额在分配块与 inode 的路径上记账：软限制可超，硬限制把 creat/write 变成 ENOSPC 一类错误。</p><footer>—— 据 McKusick 对 BSD 配额的实现；Linux quota 与 project quota 文档</footer></div><p><a href="/cs/xattr-acl">上一课</a>把权限写成 ACL。权限不限制「一个人写满整盘」。缺口是 <strong>配额</strong>：按用户、组或项目给空间与 inode 计数设上限。本课是文件系统实现课序的收口，下一课序才是 overlay 等接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多用户机器上，位图只知道盘满，不知道是谁吃的。配额文件（或隐藏 inode）记录每个 id 的已用块、已用 inode、软硬限、宽限期。缺口：记账点必须在真正分配时——稀疏写洞不记账，穿孔要减记，<a href="/cs/fs-snapshots">快照</a> 共享块不能向每个数据集收两次物理块（实现各异，课序要求你问清楚「逻辑 vs 物理」）。<code>chown</code> 要把用量从旧 uid 转到新 uid。</p><p><span class="marginnote">数字实例：给用户设软限 10 GB、硬限 12 GB、宽限期 7 天。写到 10.5 GB 时照常可写但开始警告；若 7 天内降回软限以下则无事，否则宽限期一过写入直接报错，哪怕硬限的 12 GB 还没摸到。</span></p><p><span class="marginnote">软限超了可继续写直到宽限期或硬限。journaled quota 避免崩溃后用量与位图对不上。project quota 用 inode 上的项目 id，服务目录树计费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>write</code>/<code>creat</code> 分配前：查配额，超硬限则失败，不改位图。成功则原子地：位图 + 配额计数（常进同一 <a href="/cs/ext4-journal">日志</a> 事务）。管理员用 <code>quotacheck</code> 对照 fsck 式扫描重建计数。与 VFS：具体 FS 实现 <code>quota_read</code> 或走通用 quota 文件。</p>',9)),(E(),i(n,null,{default:t(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E5%88%86%E9%85%8D%E5%9D%97%E6%88%96%20inode%22%5D%20--%3E%20Q%5B%22%E6%9F%A5%E9%85%8D%E9%A2%9D%22%5D%0A%20%20Q%20--%3E%7C%22%E7%A1%AC%E9%99%90%E6%BB%A1%22%7C%20ERR%5B%22ENOSPC%22%5D%0A%20%20Q%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20BIT%5B%22%E4%BD%8D%E5%9B%BE%E4%B8%8E%E8%AE%A1%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("配额把「盘是共享资源」收成可执行的计数器，而不是事后 "),o("code",null,"du"),e("。它不替代 "),o("a",{href:"/cs/cgroups"},"cgroup"),e(" 的内存限制：对象是持久块。也不替代存储栈的精简配置：精简是设备层「未写不占后端」；配额是 FS 层「你名下不能再占」。不要把本课写成量化风控额度。")],-1)),a[5]||(a[5]=o("p",null,"崩溃：若计数不进日志，重启后需 quotacheck，类似无日志时的 fsck 税。",-1)),(E(),i(n,null,{default:t(()=>[l(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E5%85%A5%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20C%7B%22%E7%94%A8%E9%87%8F%E5%AF%B9%E4%B8%8A%E5%93%AA%E6%9D%A1%E9%99%90%3F%22%7D%0A%20%20C%20--%3E%7C%22%E4%BD%8E%E4%BA%8E%E8%BD%AF%E9%99%90%22%7C%20OK%5B%22%E6%AD%A3%E5%B8%B8%E5%88%86%E9%85%8D%22%5D%0A%20%20C%20--%3E%7C%22%E8%B6%85%E8%BD%AF%E9%99%90%E6%9C%AA%E5%88%B0%E7%A1%AC%E9%99%90%22%7C%20GRACE%5B%22%E5%AE%BD%E9%99%90%E6%9C%9F%E5%80%92%E8%AE%A1%E6%97%B6%22%5D%0A%20%20GRACE%20--%3E%7C%22%E6%9C%9F%E5%86%85%22%7C%20OK2%5B%22%E4%BB%8D%E5%8F%AF%E5%86%99%EF%BC%8C%E5%87%BA%E8%AD%A6%E5%91%8A%22%5D%0A%20%20GRACE%20--%3E%7C%22%E5%88%B0%E6%9C%9F%22%7C%20BLOCK%5B%22%E8%A7%86%E5%90%8C%E7%A1%AC%E9%99%90%EF%BC%9A%E6%8B%92%E7%BB%9D%E5%88%86%E9%85%8D%22%5D%0A%20%20C%20--%3E%7C%22%E8%B6%85%E7%A1%AC%E9%99%90%22%7C%20ERR%5B%22ENOSPC%20%E4%B8%80%E7%B1%BB%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">这张图回答「软限、硬限、宽限期怎么互动」：软限不是硬墙，而是启动一个倒计时；初学者容易以为超了软限就写不进——实际上只要在宽限期内降回软限以下，一切照旧，到期才升级成硬墙。</span></p><p><span class="marginnote">初学者容易以为配额像 du 一样是事后统计——实际上它在分配路径上记账：位图还没改，配额先查。正因如此超限时 write 当场失败，而不是等管理员下次扫描才被打回来。</span></p><p><span class="marginnote">计数不进日志的后果：崩溃后配额文件与位图对不上，管理员必须跑 quotacheck 全盘重扫——这与无日志文件系统崩溃后跑 fsck 是同一类「重启税」，journaled quota 就是为免掉这笔税而把计数塞进与位图同一个事务。</span></p><p>实现上：journaled quota 把计数放进与位图同一事务，避免崩溃后用量撒谎。项目配额靠 inode 上的项目 id，mv 跨项目要转账，和 chown 转 uid 是同一类记账。 读法上只引用<a href="/cs/xattr-acl">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>配额</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每个发行版的 <code>edquota</code> 教程写进正文。不保证网络 FS 上服务端与客户端配额哪边执行。文件系统实现课序到此：布局、日志、COW、检查、映射、洞、属性、计数都已钉住。下一课序从「单机盘上对象」走到「把一棵树叠到另一棵上」：overlayfs。</p><p>版本字段会变，课序钉的是机制对象「配额」，不是某一主线内核的结构体名。 后课默认：分配可被配额挡住。联合挂载如何叠 lower/upper，下一课 overlayfs。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配额在分配路径记账；硬限失败，软限警告。</li><li>快照与稀疏要分清计的是什么。</li><li>联合挂载是下一课序。</li><li>出处：McKusick, <em>FreeBSD</em>；Linux quota 文档；<em>OSTEP</em> 对分配的背景。</li></ul>',11))])}const _=d(A,[["render",u]]);export{q as __pageData,_ as default};
